{
  "doc_type": "Merkblatt",
  "audience": "Schülerinnen und Schüler der 2. Sekundarklasse",
  "core": {
    "what": {
      "text": "Die Schnupperwoche ist eine verpflichtende Schnupperlehre in einem Betrieb deiner Wahl für die 2. Sekundarklassen.",
      "segment_ids": ["s0003", "s0004"]
    },
    "must_do": {
      "text": "Du suchst dir selbst einen Schnupperplatz, gibst die Betriebsbestätigung bis 19.02.2027 ab und reichst den Schnupperbericht bis 02.04.2027 ein.",
      "segment_ids": ["s0007", "s0008", "s0021"]
    },
    "deadline": {
      "text": "Bestätigung bis 19.02.2027, Meldung bei fehlendem Platz bis 05.02.2027, Bericht bis 02.04.2027.",
      "segment_ids": ["s0008", "s0009", "s0021"]
    },
    "cost": {
      "text": "Verpflegung und Wegkosten gehen zu Lasten der Erziehungsberechtigten; die Schule erstattet bis zu 30 CHF pro Woche gegen Beleg.",
      "segment_ids": ["s0016", "s0017"]
    },
    "contact": {
      "text": "Klassenlehrperson, Schulsekretariat (Telefon 0441234570, E‑Mail sekretariat@sek-musterwil.example) oder das Berufsinformationszentrum (BIZ) in Musterwil.",
      "segment_ids": ["s0010", "s0013", "s0023"]
    }
  },
  "facts": [
    {
      "id": "f01",
      "kind": "deadline",
      "text": "Die vom Betrieb ausgefüllte Bestätigung muss bis 19.02.2027 abgegeben werden.",
      "value_norm": "2027-02-19",
      "segment_ids": ["s0008"],
      "must_keep": true
    },
    {
      "id": "f02",
      "kind": "deadline",
      "text": "Fehlt bis 05.02.2027 ein Platz, muss man sich sofort bei der Klassenlehrperson melden.",
      "value_norm": "2027-02-05",
      "segment_ids": ["s0009"],
      "must_keep": true
    },
    {
      "id": "f03",
      "kind": "deadline",
      "text": "Der Schnupperbericht ist bis spätestens 02.04.2027 einzureichen.",
      "value_norm": "2027-04-02",
      "segment_ids": ["s0021"],
      "must_keep": true
    },
    {
      "id": "f04",
      "kind": "amount",
      "text": "Die Schule erstattet höchstens 30 CHF pro Woche für Fahrten mit dem öffentlichen Verkehr.",
      "value_norm": "30",
      "segment_ids": ["s0017"],
      "must_keep": true
    },
    {
      "id": "f05",
      "kind": "obligation",
      "text": "Die Teilnahme an der Schnupperwoche ist für alle obligatorisch.",
      "value_norm": null,
      "segment_ids": ["s0006"],
      "must_keep": true
    },
    {
      "id": "f06",
      "kind": "obligation",
      "text": "Die tägliche Arbeitszeit darf höchstens 8 Stunden betragen.",
      "value_norm": null,
      "segment_ids": ["s0012"],
      "must_keep": true
    },
    {
      "id": "f07",
      "kind": "obligation",
      "text": "Bei Krankheit oder Unfall muss der Betrieb und das Schulsekretariat bis 07:30 Uhr informiert werden.",
      "value_norm": "07:30",
      "segment_ids": ["s0013"],
      "must_keep": true
    },
    {
      "id": "f08",
      "kind": "obligation",
      "text": "Für Absenzen von mehr als 2 Tagen ist ein Arztzeugnis erforderlich.",
      "value_norm": null,
      "segment_ids": ["s0014"],
      "must_keep": true
    },
    {
      "id": "f09",
      "kind": "right",
      "text": "Während der Schnupperlehre bist du über die Schule unfallversichert.",
      "value_norm": null,
      "segment_ids": ["s0018"],
      "must_keep": true
    },
    {
      "id": "f10",
      "kind": "condition",
      "text": "Kosten für Verpflegung und Arbeitsweg gehen zulasten der Erziehungsberechtigten.",
      "value_norm": null,
      "segment_ids": ["s0016"],
      "must_keep": true
    },
    {
      "id": "f11",
      "kind": "contact",
      "text": "Berufsinformationszentrum (BIZ), Bahnhofstrasse 10, 9999 Musterwil, geöffnet Mo‑Do 13:30‑17:30.",
      "value_norm": null,
      "segment_ids": ["s0010"],
      "must_keep": true
    },
    {
      "id": "f12",
      "kind": "contact",
      "text": "Schulsekretariat Telefon 0441234570.",
      "value_norm": "0441234570",
      "segment_ids": ["s0013"],
      "must_keep": true
    },
    {
      "id": "f13",
      "kind": "contact",
      "text": "E‑Mail sekretariat@sek-musterwil.example für Fragen.",
      "value_norm": "sekretariat@sek-musterwil.example",
      "segment_ids": ["s0023"],
      "must_keep": true
    }
  ],
  "hard_terms": [
    {
      "term": "Schnupperwoche",
      "explanation": "Eine einwöchige Praxisphase, in der Schülerinnen und Schüler einen Betrieb kennenlernen.",
      "segment_ids": ["s0001", "s0003"]
    },
    {
      "term": "Schnupperlehre",
      "explanation": "Ein kurzer Einblick in einen Beruf, der während der Schnupperwoche gemacht wird.",
      "segment_ids": ["s0004"]
    },
    {
      "term": "Berufsinformationszentrum (BIZ)",
      "explanation": "Eine Beratungsstelle, die bei der Berufswahl und der Suche nach einem Praktikumsplatz hilft.",
      "segment_ids": ["s0010"]
    },
    {
      "term": "Klassenlehrperson",
      "explanation": "Lehrkraft, die für die Klasse verantwortlich ist und als Ansprechpartner dient.",
      "segment_ids": ["s0008", "s0009", "s0023"]
    },
    {
      "term": "Schulsekretariat",
      "explanation": "Die Verwaltungsstelle der Schule, die Telefon- und E‑Mail‑Anfragen bearbeitet.",
      "segment_ids": ["s0013", "s0023"]
    },
    {
      "term": "Schnuppertagebuch",
      "explanation": "Ein Tagebuch, in dem die Schülerin/der Schüler die Erlebnisse während der Schnupperwoche festhält.",
      "segment_ids": ["s0020"]
    },
    {
      "term": "Haftpflichtversicherung",
      "explanation": "Versicherung, die Schäden abdeckt, die man anderen zufügt; hier Verantwortung der Eltern.",
      "segment_ids": ["s0019"]
    }
  ],
  "omit_candidates": [
    {
      "segment_ids": ["s0005"],
      "reason": "Verweis auf Lehrplan, für das Verständnis nicht nötig."
    },
    {
      "segment_ids": ["s0019"],
      "reason": "Hinweis zur Haftpflichtversicherung ist Hintergrundinformation."
    },
    {
      "segment_ids": ["s0025", "s0026", "s0027"],
      "reason": "Schlussformel und Gruß, nicht zwingend für die Handlung."
    }
  ]
}

